//   每次跳的格数 d（d 至少是 1）。
// 青蛙从第 a 格出发，每次往前跳 d 格，不能越过第 n 格。
//   输出它踩过的每一格，包括起点，每个数占一行。
//   a 比 n 大就什么也不输出。
// 例如输入：2 10 3
// 应该输出（每个一行）：2、5、8
// ↓ 从这里开始写

#include <iostream>
using namespace std;

int main() {
    int a = 0, n = 0, d = 0;
    cin >> a >> n >> d;
    return 0;
}
